int binarySearch(const std::vector<int>& arr, int target) {
	int left = 0, right = arr.size() - 1;
	while (left <= right) {
		int mid = left + (right - left) / 2;
		if (arr[mid] == target) return mid;
		if (arr[mid] < target) left = mid + 1;
		else right = mid - 1;
	}
	return -1;
}

template <typename T>
T maxElement(const std::vector<T>& vec) {
	if (vec.empty()) throw std::runtime_error("empty vector");
	T result = vec[0];
	for (const T& val : vec) {
		if (val > result) result = val;
	}
	return result;
}

struct Node {
	int val;
	Node* next;
	Node(int val) : val(val), next(nullptr) {}
};

class LinkedList {
	Node* head = nullptr;
public:
	void push(int val) {
		Node* node = new Node(val);
		node->next = head;
		head = node;
	}
	~LinkedList() {
		while (head) {
			Node* tmp = head;
			head = head->next;
			delete tmp;
		}
	}
};

