void merge(std::vector<int>& arr, int l, int m, int r) {
	std::vector<int> left(arr.begin() + l, arr.begin() + m + 1);
	std::vector<int> right(arr.begin() + m + 1, arr.begin() + r + 1);
	int i = 0, j = 0, k = l;
	while (i < left.size() && j < right.size())
		arr[k++] = left[i] <= right[j] ? left[i++] : right[j++];
	while (i < left.size()) arr[k++] = left[i++];
	while (j < right.size()) arr[k++] = right[j++];
}

std::vector<std::string> split(const std::string& s, char delim) {
	std::vector<std::string> tokens;
	std::stringstream ss(s);
	std::string token;
	while (std::getline(ss, token, delim)) {
		if (!token.empty()) tokens.push_back(token);
	}
	return tokens;
}

template <typename T>
class Range {
	T start_, end_, step_;
public:
	Range(T start, T end, T step = 1) : start_(start), end_(end), step_(step) {}
	struct Iterator {
		T val, step;
		T operator*() const { return val; }
		Iterator& operator++() { val += step; return *this; }
		bool operator!=(const Iterator& o) const { return val < o.val; }
	};
	Iterator begin() const { return {start_, step_}; }
	Iterator end() const { return {end_, step_}; }
};
